import{_ as n,c as i,o as r,a2 as a}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"Nutzungsbedingungen","description":"Die einfachen Bedingungen für die Nutzung von qDiff auf Ihrem Mac.","frontmatter":{"title":"Nutzungsbedingungen","description":"Die einfachen Bedingungen für die Nutzung von qDiff auf Ihrem Mac."},"headers":[],"relativePath":"de/terms/index.md","filePath":"de/terms/index.md","lastUpdated":1794296122000}'),t={name:"de/terms/index.md"};function s(d,e,u,l,h,o){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="nutzungsbedingungen" tabindex="-1">Nutzungsbedingungen <a class="header-anchor" href="#nutzungsbedingungen" aria-label="Permalink to &quot;Nutzungsbedingungen&quot;">​</a></h1><p><em>Zuletzt aktualisiert: 6. November 2026</em></p><p>Vielen Dank, dass Sie qDiff nutzen. Diese Bedingungen gelten für die App und diese Website.</p><h2 id="nutzung-der-app" tabindex="-1">Nutzung der App <a class="header-anchor" href="#nutzung-der-app" aria-label="Permalink to &quot;Nutzung der App&quot;">​</a></h2><p>qDiff wird zum Vergleichen und Organisieren Ihrer eigenen Dateien bereitgestellt. Sie dürfen es zu Hause und bei der Arbeit nutzen. Sie bleiben verantwortlich für die Dateien, die Sie öffnen, sowie für Sicherungskopien aller wichtigen Inhalte.</p><p>Die App wird „wie besehen“ bereitgestellt. Wir arbeiten hart daran, sie zuverlässig zu machen, können aber nicht versprechen, dass sie unterbrechungsfrei oder fehlerfrei läuft, und wir haften nicht für verlorene Daten. Bitte erstellen Sie eine Sicherung, bevor Sie Dateien synchronisieren oder löschen.</p><h2 id="kostenlose-version-und-kauf" tabindex="-1">Kostenlose Version und Kauf <a class="header-anchor" href="#kostenlose-version-und-kauf" aria-label="Permalink to &quot;Kostenlose Version und Kauf&quot;">​</a></h2><p>Alle Vergleichsfunktionen sind kostenlos. Die kostenlose Version zeigt einen kleinen Hinweis in der Tableiste; ein einmaliger, nicht verbrauchbarer Kauf entfernt ihn und schließt künftige Premium-Extras ein. Es gibt kein Abo.</p><p>Kauf, Erstattungen und Wiederherstellung werden über den Mac App Store gemäß den Bedingungen von Apple und Ihrer Apple ID abgewickelt. Wir erhalten Ihre Zahlungsinformationen nicht.</p><h2 id="ihre-inhalte" tabindex="-1">Ihre Inhalte <a class="header-anchor" href="#ihre-inhalte" aria-label="Permalink to &quot;Ihre Inhalte&quot;">​</a></h2><p>Wir erheben keinerlei Ansprüche auf Ihre Dateien und erhalten sie auch nicht. Details finden Sie in der <a href="./../privacy/">Datenschutzerklärung</a>.</p><h2 id="diese-website" tabindex="-1">Diese Website <a class="header-anchor" href="#diese-website" aria-label="Permalink to &quot;Diese Website&quot;">​</a></h2><p>Die Inhalte dieser Website dienen nur der Information. Produktbeschreibungen können aktualisiert werden, während qDiff weiter verbessert wird.</p><h2 id="anderungen" tabindex="-1">Änderungen <a class="header-anchor" href="#anderungen" aria-label="Permalink to &quot;Änderungen&quot;">​</a></h2><p>Wir können diese Bedingungen aktualisieren; das oben genannte Datum ändert sich dann entsprechend. Wenn Sie qDiff nach einer Aktualisierung weiter nutzen, akzeptieren Sie die geänderten Bedingungen.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Fragen? Schreiben Sie an <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>.</p>',17)])])}const f=n(t,[["render",s]]);export{c as __pageData,f as default};
